/**
 * Artyom.js - Voice Recognition and Synthesis Library
 * Build - Fixed strobe effect (blinking mic) and auto-turn off
 */
(function(window){
    'use strict';
    if(typeof window === 'undefined') return;
    
    var Artyom = function(){
        this.artyomProperties = {
            lang: "es-ES", recognizing: false, continuous: false, listen: false, volume: 1, speed: 1, mode: "normal", debug: false
        };
        this.artyomCommands = [];
        
        window.SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition || null;
        window.SpeechGrammarList = window.SpeechGrammarList || window.webkitSpeechGrammarList || null;
        
        if(window.SpeechRecognition !== null){
            this.artyomWebkitSpeechRecognition = new window.SpeechRecognition();
            var _this = this;
            
            this.artyomWebkitSpeechRecognition.continuous = false;
            this.artyomWebkitSpeechRecognition.interimResults = false;
            this.artyomWebkitSpeechRecognition.lang = "es-ES";
            
            this.artyomWebkitSpeechRecognition.onstart = function(){
                _this.artyomProperties.recognizing = true;
            };
            
            this.artyomWebkitSpeechRecognition.onerror = function(event){
                if (event.error === 'network') return;
                console.error("Artyom error: ", event.error);
            };
            
            this.artyomWebkitSpeechRecognition.onend = function(){
                _this.artyomProperties.recognizing = false;
                if(_this.artyomProperties.listen === true){
                    // PAUSA DE MEDIO SEGUNDO PARA EVITAR EL PARPADEO
                    setTimeout(function(){
                        try { _this.artyomWebkitSpeechRecognition.start(); } catch(e) {}
                    }, 500);
                }
            };
            
            this.artyomWebkitSpeechRecognition.onresult = function(event){
                for (var i = event.resultIndex; i < event.results.length; ++i) {
                    if (event.results[i].isFinal) {
                        var text = event.results[i][0].transcript;
                        _this.execute(text);
                    }
                }
            };
        }
    };
    
    Artyom.prototype.addCommands = function(commands){
        var _this = this;
        if(Array.isArray(commands)){ commands.forEach(function(cmd){ _this.artyomCommands.push(cmd); }); }
        else{ this.artyomCommands.push(commands); }
    };
    
    Artyom.prototype.initialize = function(config){
        var _this = this;
        return new Promise(function(resolve, reject){
            if(config.lang) _this.artyomProperties.lang = config.lang;
            if(config.continuous !== undefined) _this.artyomWebkitSpeechRecognition.continuous = config.continuous;
            if(config.listen !== undefined) _this.artyomProperties.listen = config.listen;
            
            if(_this.artyomProperties.listen === true){
                try{ _this.artyomWebkitSpeechRecognition.start(); }catch(e){}
            }
            resolve();
        });
    };
    
    Artyom.prototype.execute = function(text){
        console.log("🎙️ Escuchado con éxito: " + text);
        for(var i = 0; i < this.artyomCommands.length; i++){
            var command = this.artyomCommands[i];
            var indexes = command.indexes;
            for(var j = 0; j < indexes.length; j++){
                if(text.toLowerCase().trim().indexOf(indexes[j].toLowerCase().trim()) !== -1){
                    // ¡Clave! Apagamos el micrófono inmediatamente al reconocer la orden
                    this.dontListen(); 
                    command.action();
                    return true;
                }
            }
        }
        return false;
    };
    
    Artyom.prototype.say = function(message){
        if(window.speechSynthesis){
            var msg = new SpeechSynthesisUtterance(message);
            msg.lang = this.artyomProperties.lang;
            msg.rate = this.artyomProperties.speed;
            window.speechSynthesis.speak(msg);
        }
    };
    
    Artyom.prototype.dontListen = function(){
        this.artyomProperties.listen = false;
        this.artyomWebkitSpeechRecognition.stop();
    };
    
    Artyom.prototype.fatality = function(){
        this.artyomProperties.listen = false;
        this.artyomWebkitSpeechRecognition.stop();
    };
    
    window.Artyom = Artyom;
})(window);